    public int MaxItems { get; set; }

    public MyControl()
    {
        _statusStrip = new StatusStrip();

        // .NET 9 breaking change: StatusStrip no longer defaults to system rendering.
        // Explicitly set the render mode to preserve the previous appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.System;

        Controls.Add(_statusStrip);
    }

    /// <summary>
    /// Shows a dropdown editor, guarding against the .NET 9 breaking change
    /// where passing null to DropDownControl throws ArgumentNullException.
    /// </summary>
    public void ShowDropDown(IWindowsFormsEditorService editorService, Control dropdown)
    {
        // .NET 9: DropDownControl now throws ArgumentNullException if control is null.
        if (dropdown is null)
            return;

        editorService.DropDownControl(dropdown);
    }

    // .NET 9: Prefer LibraryImport (source-generated P/Invoke) over DllImport
    // for better performance and AOT compatibility.
    [LibraryImport("user32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool SetWindowPos(
        IntPtr hWnd,
        IntPtr hWndInsertAfter,
        int x, int y, int cx, int cy,
        uint uFlags);

    [LibraryImport("ole32.dll")]
    private static partial int CoInitializeEx(IntPtr pvReserved, uint dwCoInit);

    public void InitializeCom()
    {
        const uint COINIT_APARTMENTTHREADED = 0x2;
        int hr = CoInitializeEx(IntPtr.Zero, COINIT_APARTMENTTHREADED);
        if (hr < 0)
            Marshal.ThrowExceptionForHR(hr);
    }
}

